    vol=[]
    cur=[]
    for m in re.finditer(r'Volumes!([A-Z]+)(\d+)', v):
        vol.append((m.group(1), int(m.group(2))))
    for m in re.finditer(r'Curves!([A-Z]+)(\d+)', v):
        cur.append((m.group(1), int(m.group(2))))
    return vol,cur
for col in 'CDEFGHI':
