        v=ws[f'{col}{r}'].value
        if v is None: continue
        if not (isinstance(v,str) and v.startswith('=')):
            continue
        vol,cur=parse_refs(v)
        ev=vol_col[col]; ec=cur_col[col]
        if r==6:
            exp_vol=[(ev,4)]; exp_cur=[(ec,5)]
            # but order maybe cur then vol for G? Not matter
        else:
            exp_vol=[(ev,r-2),(ev,r-1)]
            exp_cur=[(ec,r-1),(ec,r)]
