        if sorted(vol)!=sorted(exp_vol) or sorted(cur)!=sorted(exp_cur):
            print(f'ROW PATTERN MISMATCH {col}{r}: formula={v}')
            print('  vol',vol,'exp',sorted(exp_vol),'cur',cur,'exp',sorted(exp_cur))
